<script setup>
import {computed,onMounted,onUnmounted,ref,reactive,watch} from 'vue'
import {api,state,notify,bytes} from '../lib'
import Icon from './Icon.vue'
import RoundedSelect from './RoundedSelect.vue'
import VirtualList from './VirtualList.vue'
import Modal from './Modal.vue'
const storage=ref(''),directory=ref(''),trail=ref([]),files=ref([]),items=ref([]),selected=ref([]),query=ref(''),loading=ref(false),busy=ref(false),progress=ref({}),taskId=ref(''),matching=ref(null),confirmation=ref(null),settingsOpen=ref(false)
const match=reactive({tmdb:'',kind:'movie'}),settings=reactive({writeMode:'missing',episodes:true,fanart:false,actors:false,excluded:''})
const pools=computed(()=>state.storages.filter(s=>s.enabled).map(s=>({value:s.id,label:s.name,provider:s.type})))
const filtered=computed(()=>files.value.filter(f=>f.isDir||/\.(mp4|mkv|avi|mov|wmv|flv|webm|m4v|ts|m2ts|mkvb|rmvb|rm|3gp|mpg|mpeg|iso|strm)$/i.test(f.name)).filter(f=>f.name.toLowerCase().includes(query.value.toLowerCase())))
let alive=true,request=0,timer
const status=item=>({ok:'已完成',pending:'待刮削',miss:'未识别',doubt:'待确认',error:'失败'}[item?.status]||'未识别')
function result(file){return items.value.find(i=>i.path===file.name)}
async function load(){const ticket=++request,sid=storage.value,dir=directory.value;if(!sid)return;loading.value=true;try{const data=await api(`/directory-scrape/files?${new URLSearchParams({storageId:sid,directory:dir})}`);if(alive&&ticket===request){files.value=data.files;items.value=data.items;taskId.value=data.taskId;directory.value=data.directory;selected.value=[]}}catch(e){if(alive&&ticket===request)notify(e.message,true)}finally{if(alive&&ticket===request)loading.value=false}}
watch(storage,()=>{request++;directory.value='';trail.value=[];files.value=[];items.value=[];load()})
watch(pools,options=>{if(!options.some(s=>s.value===storage.value))storage.value=options[0]?.value||''},{immediate:true})
function enter(file){trail.value.push({id:directory.value,name:file.name});directory.value=file.id;load()}
function back(){const prev=trail.value.pop();directory.value=prev?.id||'';load()}
function choose(file){if(file.isDir){enter(file);return}matching.value=file;Object.assign(match,{tmdb:result(file)?.tmdb||'',kind:result(file)?.kind||'movie'})}
async function execute(action,ids=selected.value){busy.value=true;try{progress.value=await api(`/directory-scrape/${action}`,'POST',{storageId:storage.value,directory:directory.value,ids,...(action==='match'?{tmdb:Number(match.tmdb),kind:match.kind}:{})});confirmation.value=null;matching.value=null;notify(action==='identify'?'目录识别已启动':'目录刮削已启动')}catch(e){notify(e.message,true)}finally{busy.value=false}}
async function poll(){try{const old=progress.value;const data=await api('/strm-scrape/status');if(!alive)return;progress.value=data;if(old.running&&!data.running){await load();notify(data.message||'刮削已结束',!!data.error||data.failed>0)}}catch(e){if(alive)notify(e.message,true)}finally{if(alive)timer=setTimeout(poll,2000)}}
async function stop(){try{await api('/strm-scrape/stop','POST',{});notify('正在停止刮削任务')}catch(e){notify(e.message,true)}}
async function saveSettings(){busy.value=true;try{await api('/strm-scrape/settings','PUT',settings);settingsOpen.value=false;notify('刮削设置已保存')}catch(e){notify(e.message,true)}finally{busy.value=false}}
onMounted(async()=>{poll();try{Object.assign(settings,await api('/strm-scrape/settings'))}catch(e){notify(e.message,true)}})
onUnmounted(()=>{alive=false;request++;clearTimeout(timer)})
</script>
<template>
 <section class="directory-scrape-panel" aria-label="目录刮削">
  <header class="directory-scrape-toolbar"><RoundedSelect v-model="storage" label="刮削存储池" :options="pools"/><button class="icon-btn" aria-label="上级目录" :disabled="!trail.length||loading" @click="back"><Icon name="ArrowUp"/></button><span class="directory-scrape-location" :data-tooltip="trail.map(i=>i.name).join('/')">{{trail.map(i=>i.name).join(' / ')||'根目录'}}</span><button class="icon-btn" aria-label="刷新目录" :disabled="loading" @click="load"><Icon name="RefreshCw" :class="{spin:loading}"/></button><div class="search-field"><Icon name="Search"/><input v-model="query" aria-label="搜索目录媒体" placeholder="搜索文件名称"/></div><button class="btn" @click="settingsOpen=true"><Icon name="Settings2"/>刮削设置</button></header>
  <div class="directory-scrape-actions"><span>{{selected.length?`已选 ${selected.length} 项`:`${filtered.length} 项`}}</span><button class="btn" :disabled="!storage||loading||busy||progress.running" @click="confirmation='identify'"><Icon name="ScanSearch"/>识别</button><button class="btn primary" :disabled="!storage||loading||busy||progress.running" @click="confirmation='run'"><Icon name="Play"/>刮削</button><button v-if="progress.running" class="btn" @click="stop"><Icon name="Square"/>停止</button></div>
  <div v-if="progress.running" class="directory-scrape-progress"><span>{{progress.message}} · {{progress.done||0}} / {{progress.total||0}}</span><progress :value="progress.done||0" :max="progress.total||1"/></div>
  <div class="directory-scrape-columns" aria-hidden="true"><span>文件名称</span><span>识别结果</span><span>大小</span><span>状态</span></div>
  <div class="directory-scrape-list"><p v-if="loading" class="small-empty">正在读取目录…</p><VirtualList v-else :items="filtered" :row-height="54"><template #default="{item}"><div class="directory-scrape-row"><div><input v-model="selected" type="checkbox" :value="item.id" :aria-label="`选择 ${item.name}`"/><button class="text-btn" @click="choose(item)"><Icon :name="item.isDir?'Folder':'FileVideo'"/><span :data-tooltip="item.name" data-tooltip-stationary data-tooltip-delay="300">{{item.name}}</span></button></div><span :data-tooltip="result(item)?.matchedTitle||result(item)?.title">{{result(item)?.matchedTitle||result(item)?.title||'—'}}</span><small>{{item.isDir?'—':bytes(item.size)}}</small><small>{{item.isDir?'目录':status(result(item))}}</small></div></template></VirtualList><p v-if="!loading&&!filtered.length" class="small-empty">当前目录没有媒体文件</p></div>
 </section>
 <Modal v-if="confirmation" title="确认目录刮削" compact confirmation @close="!busy&&(confirmation=null)"><div class="modal-body">{{confirmation==='identify'?'识别所选媒体，不写入文件。':'将向所选媒体所在目录写入NFO和海报，按刮削设置补缺或覆盖。'}}未选择条目时处理当前目录及子目录。</div><footer class="modal-footer"><button class="btn" :disabled="busy" @click="confirmation=null">取消</button><button class="btn primary" :disabled="busy" @click="execute(confirmation)">确认{{confirmation==='identify'?'识别':'刮削'}}</button></footer></Modal>
 <Modal v-if="matching" title="手动识别目录媒体" compact @close="!busy&&(matching=null)"><div class="modal-body"><p :data-tooltip="matching.name">{{matching.name}}</p><div class="form-grid"><label>媒体类型<RoundedSelect v-model="match.kind" label="媒体类型" :options="[{value:'movie',label:'电影'},{value:'tv',label:'剧集'}]"/></label><label>TMDB ID<input v-model="match.tmdb" aria-label="TMDB ID" inputmode="numeric"/></label></div></div><footer class="modal-footer"><button class="btn" @click="matching=null">取消</button><button class="btn primary" :disabled="busy||progress.running||!/^\d+$/.test(String(match.tmdb))||Number(match.tmdb)<1" @click="execute('match',[matching.id])">识别并刮削</button></footer></Modal>
 <Modal v-if="settingsOpen" title="刮削设置" compact @close="!busy&&(settingsOpen=false)"><form @submit.prevent="saveSettings"><div class="modal-body form-grid"><label class="full">写入方式<RoundedSelect v-model="settings.writeMode" label="写入方式" :options="[{value:'missing',label:'仅补缺少文件'},{value:'overwrite',label:'覆盖元数据'}]"/></label><label class="switch-label">分集信息<input v-model="settings.episodes" type="checkbox" class="switch"/></label><label class="switch-label">背景图片<input v-model="settings.fanart" type="checkbox" class="switch"/></label><label class="switch-label">演员信息<input v-model="settings.actors" type="checkbox" class="switch"/></label><label class="full">排除目录<input v-model="settings.excluded"/></label></div><footer class="modal-footer"><button class="btn primary" :disabled="busy">保存设置</button></footer></form></Modal>
</template>
<style scoped>
.directory-scrape-panel{border:1px solid var(--border);border-radius:10px;background:var(--surface);overflow:hidden;min-width:0}.directory-scrape-toolbar{display:flex;align-items:center;gap:10px;padding:14px;flex-wrap:wrap}.directory-scrape-toolbar>.rounded-select{width:180px;max-width:100%}.directory-scrape-location{flex:1;min-width:60px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px}.directory-scrape-toolbar .search-field{width:200px;max-width:100%}.directory-scrape-actions{display:flex;align-items:center;gap:10px;padding:10px 14px;border-block:1px solid var(--border)}.directory-scrape-actions>span{margin-right:auto;color:var(--muted);font-size:13px}.directory-scrape-list{height:min(620px,65dvh)}.directory-scrape-columns,.directory-scrape-row{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr) 90px 70px;align-items:center;gap:16px;padding:0 16px;font-size:13px}.directory-scrape-columns{height:38px;background:var(--layer-frame);color:var(--muted)}.directory-scrape-row{height:54px;border-bottom:1px solid var(--border)}.directory-scrape-row>div,.directory-scrape-row .text-btn{display:flex;align-items:center;gap:10px;min-width:0}.directory-scrape-row input{width:16px;flex:none}.directory-scrape-row .text-btn{max-width:100%}.directory-scrape-row svg{flex:none}.directory-scrape-row span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.directory-scrape-progress{padding:12px 16px;display:grid;gap:8px;font-size:13px}.directory-scrape-progress progress{width:100%}@media(max-width:600px){.directory-scrape-columns,.directory-scrape-row{grid-template-columns:minmax(0,1fr) 64px;gap:10px;padding-inline:10px}.directory-scrape-columns>:nth-child(2),.directory-scrape-columns>:nth-child(3),.directory-scrape-row>:nth-child(2),.directory-scrape-row>:nth-child(3){display:none}.directory-scrape-toolbar .search-field{width:auto;flex:1}}
</style>
